-- 4a BEHAVIOURAL: the FK fires, induced against a uuid that cannot exist
BEGIN
  INSERT INTO form_submissions (site_id, intent, payload)
  VALUES ('00000000-0000-0000-0000-000000000000'::uuid,'verify_probe','{}'::jsonb);
EXCEPTION WHEN foreign_key_violation THEN v_ok := true;
END;
IF NOT v_ok THEN RAISE EXCEPTION 'verify: ... the FK is not enforced'; END IF;

-- 4b DECLARATIVE: and its action is RESTRICT, not CASCADE
IF NOT EXISTS (SELECT 1 FROM pg_constraint
   WHERE conrelid='public.form_submissions'::regclass
     AND confrelid='public.sites'::regclass
     AND contype='f' AND confdeltype='r')
THEN RAISE EXCEPTION 'verify: ... could destroy leads'; END IF;

IF v_subs > 0 THEN
  RAISE EXCEPTION 'REFUSING: form_submissions holds % row(s). These are real enquiries and this migration is their only store. Export them, delete them deliberately, then re-run this rollback.', v_subs;
END IF;
DROP TABLE IF EXISTS form_submissions;
DROP TABLE IF EXISTS site_form_routes;
